package cn.zhuatech.syntheticdata.controller;import cn.zhuatech.syntheticdata.common.ApiResponse;import cn.zhuatech.syntheticdata.service.SyntheticDatasetReleaseService;import jakarta.validation.Valid;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/synthetic-data")public class SyntheticDatasetReleaseController{private final SyntheticDatasetReleaseService service;public SyntheticDatasetReleaseController(SyntheticDatasetReleaseService s){service=s;}@PostMapping("/release-evaluation")@PreAuthorize("hasAnyRole('ADMIN','DATA_ENGINEER')")public ApiResponse<SyntheticDatasetReleaseService.Result>evaluate(@Valid@RequestBody SyntheticDatasetReleaseService.Request r){return ApiResponse.ok("合成数据发布评估完成",service.evaluate(r));}}
